const CASES=[
 {id:'molar',num:'16',name:'Frau Lena Neumann',age:38,title:'Tiefe Karies am Zahn 16',subtitle:'Posterior restorative dentistry',complaint:'„Ich habe beim Kauen rechts oben Beschwerden. Kaltes ist unangenehm, aber der Schmerz hört schnell wieder auf.“',history:'Die Beschwerden bestehen seit etwa drei Wochen. Keine Spontanschmerzen, keine Schwellung, keine Fieberangabe. Regelmäßige Medikation: keine. Allergien werden verneint.',exam:'Zahn 16: klinisch okklusal-approximale Kavitation; sensibel auf Kälte, Reaktion klingt rasch ab; Perkussion unauffällig. Approximaler Kontakt und parodontale Situation müssen erhoben werden.',risk:'Tiefe Karies mit erhaltener Vitalität; Pulpastatus und Restaurierbarkeit vor jeder definitiven Therapie überprüfen.',planA:'Direkte adhäsive Restauration, falls Defektgröße, Randverhältnisse und Höckerstabilität dies zulassen.',planB:'Indirekte Teilkrone/Onlay bei größerem Substanzverlust und erhöhtem Höckerfrakturrisiko.',diagnosis:'Karies dentinum, pulpanah möglich; pulpal diagnosis needs clinical testing',patientReply:['Seit drei Wochen. Vor allem, wenn ich etwas Hartes kaue.','Nur kurz beim Kalten, nicht stundenlang.','Nein, nachts tut es nicht von selbst weh.','Mir sind keine Allergien bekannt, ich nehme keine Medikamente.','Ja, Sie können sich den Zahn ansehen.','Ist die Behandlung schmerzhaft?','Ja, bitte erklären Sie mir die Alternativen.'],vocab:[['die Karies','tooth decay'],['die Füllung','restoration'],['die Betäubung','local anaesthesia'],['die Teilkrone','partial crown'],['die Kofferdamisolierung','rubber dam isolation'],['okklusal / approximal','occlusal / proximal']],keywords:['16','Karies','Kälte','Vital','adhäsiv'],prepType:'MOD',qp:'Was spricht für eine direkte Füllung statt einer Teilkrone?'},
 {id:'endo',num:'36',name:'Herr Daniel Krüger',age:45,title:'Pulpaschmerz am Zahn 36',subtitle:'Endodontics · differential diagnosis',complaint:'„Links unten habe ich seit gestern starke Zahnschmerzen. Bei Kaltem tut es lange weh und nachts werde ich wach.“',history:'Seit einigen Wochen Kälteempfindlichkeit; seit gestern anhaltender Schmerz, auch spontan. Kein berichtetes Fieber und keine Gesichtsschwellung. Medikamente und Allergien müssen aktiv erfragt werden.',exam:'Zahn 36 mit tiefer kariöser Läsion. Reizantwort und Perkussion sind systematisch zu untersuchen. Ein Röntgenbefund allein reicht für die pulpare Diagnose nicht aus.',risk:'Verdacht auf symptomatische irreversible Pulpitis, Differenzialdiagnose und Zahnerhaltungsfähigkeit abklären.',planA:'Nach Diagnose und Einwilligung endodontische Therapie zum Zahnerhalt mit adäquater definitiver koronaler Versorgung.',planB:'Extraktion nach Aufklärung, falls Zahn nicht erhaltungswürdig ist oder der Patient nach Beratung diesen Weg wählt.',diagnosis:'Verdacht auf symptomatische irreversible Pulpitis',patientReply:['Das hat vor einigen Wochen beim Kalten angefangen.','Jetzt hält der Schmerz nach dem Kältereiz länger an.','Ja, ich bin sogar nachts wegen der Schmerzen aufgewacht.','Nein, mein Gesicht ist nicht geschwollen und Fieber habe ich nicht bemerkt.','Ja, Sie dürfen den Zahn testen und untersuchen.','Muss der Zahn gezogen werden?','Ich möchte den Zahn wenn möglich behalten.'],vocab:[['die Pulpitis','pulp inflammation'],['die Wurzelkanalbehandlung','root canal treatment'],['die Spontanschmerzen','spontaneous pain'],['der Kältetest','cold sensitivity test'],['die Perkussion','percussion'],['die Wurzelspitze','root apex']],keywords:['36','Schmerz','Pulpitis','Kälte','Endodont'],prepType:'ENDO',qp:'Welche Befunde stützen eine symptomatische irreversible Pulpitis?'},
 {id:'anterior',num:'11',name:'Frau Sofia Berger',age:29,title:'Frontzahntrauma am Zahn 11',subtitle:'Anterior composite · trauma triage',complaint:'„Ich bin vor zwei Tagen gestürzt. Ein Stück vom oberen Schneidezahn ist abgebrochen. Jetzt stört mich die Kante.“',history:'Sturz vor 48 Stunden; keine berichtete Bewusstlosigkeit, aber Unfallhergang und Begleitverletzungen sind gezielt zu erfragen. Schmerz bei Kälte möglich.',exam:'Zahn 11 mit inzisalem Substanzverlust. Vor Therapie: klinische Frakturklassifikation, Pulpa-/Sensibilitätstestung, Mobilität, Perkussion, Weichteile, Okklusion und indizierte Bildgebung.',risk:'Unkomplizierte Schmelz-Dentin-Fraktur möglich; pulpare Beteiligung, Luxation und Wurzelfraktur ausschließen.',planA:'Direkte adhäsive Kompositversorgung nach Ausschluss komplexer Verletzungen.',planB:'Je nach Defektgröße, Pulpa- und Wurzelbefund fragmentäre Wiederbefestigung, indirekte Versorgung oder weitere Behandlung.',diagnosis:'Verdacht auf unkomplizierte Kronenfraktur Zahn 11',patientReply:['Vorgestern bin ich auf einer Treppe ausgerutscht.','Nein, ich war nicht bewusstlos.','Die Ecke stört, kalte Getränke sind etwas unangenehm.','Ich habe keine bekannte Medikamentenallergie.','Ja, Sie dürfen den Zahn untersuchen.','Wird mein Zahn wieder normal aussehen?','Mir ist wichtig, dass der Zahn erhalten bleibt.'],vocab:[['die Kronenfraktur','crown fracture'],['die Schneidekante','incisal edge'],['die Sensibilitätsprüfung','sensibility testing'],['der Zahnunfall','dental trauma'],['der Kompositaufbau','composite build-up'],['die Wurzelfraktur','root fracture']],keywords:['11','Fraktur','Trauma','Pulpa','Komposit'],prepType:'INCISAL',qp:'Was muss bei Frontzahntrauma vor dem Kompositaufbau untersucht werden?'}
 ,{id:'crown',num:'26',name:'Herr Markus Seidel',age:53,title:'Kronen-/Teilkrone am Zahn 26',subtitle:'Fixed prosthodontics · impression',complaint:'„Meine große Füllung links oben ist mehrfach gebrochen. Ich kann auf dieser Seite kaum noch kauen.“',history:'Mehrfach erneuerte ausgedehnte Füllung an 26. Keine spontane Zahnschmerzen, aber Kauprobleme. Allgemeinanamnese und Erwartungen an Zahnerhalt erfragen.',exam:'Ausgedehnte Restauration mit Verdacht auf Höckenschwächung. Vor Präparation: Restzahnhartsubstanz, Pulpa, parodontale Prognose, Rissverdacht, Okklusion und restaurative Optionen prüfen.',risk:'Restaurierbarkeit und verbleibende gesunde Höcker bestimmen, ob eine Teilkrone, Vollkrone oder andere Versorgung sinnvoll ist.',planA:'Höckerüberdeckende indirekte Teilkrone/Onlay bei ausreichender Restsubstanz und passender Indikation.',planB:'Vollkrone bei entsprechender Defektausdehnung; stärkerer Zahnhartsubstanzverlust muss begründet werden.',diagnosis:'Defekte ausgedehnte Restauration Zahn 26',patientReply:['Seit einigen Monaten bricht immer wieder eine Ecke ab.','Beim Kauen ja, bei Kälte nur selten.','Nein, nachts habe ich keine Schmerzen.','Ich habe Bluthochdruck und nehme ein Medikament; den Namen bringe ich mit.','Sie dürfen den Zahn gerne untersuchen.','Muss der Zahn komplett abgeschliffen werden?','Bitte erklären Sie mir die Unterschiede zwischen Teilkrone und Krone.'],vocab:[['die Teilkrone','partial crown'],['die Verblendkrone','veneered crown'],['die Präparationsgrenze','finish line'],['die Abformung','impression'],['das Provisorium','temporary crown'],['der Biss','occlusion']],keywords:['26','Krone','Füllung','Restsubstanz'],prepType:'CROWN',qp:'Wann ist eine Teilkrone gegenüber einer Vollkrone substanzschonender?'},
 {id:'surgery',num:'48',name:'Frau Amelie Fischer',age:24,title:'Perikoronitis am Zahn 48',subtitle:'Oral surgery · instruments',complaint:'„Ganz hinten rechts unten tut das Zahnfleisch weh. Beim Essen klemme ich es manchmal ein.“',history:'Seit drei Tagen zunehmender Schmerz am teilweise durchgebrochenen 48. Allgemeinzustand, Fieber, Schwellung, Mundöffnung, Schluckbeschwerden und Risikofaktoren gezielt erfragen.',exam:'Operculum über einem teilweise durchgebrochenen 48 mit lokaler Irritation. Mundöffnung, vestibuläre Schwellung, lymphatische Zeichen, Okklusion und erforderliche Bildgebung prüfen.',risk:'Lokale Perikoronitis möglich; systemische Infektionszeichen müssen ausgeschlossen und Dringlichkeit beurteilt werden.',planA:'Bei lokalem Befund konservative Akutmaßnahmen mit Reinigung/Spülung nach Indikation, Schmerztherapie und Verlaufskontrolle.',planB:'Nach Akutphase und Indikationsprüfung operative Entfernung bei wiederkehrenden Beschwerden; Risiken und Alternativen aufklären.',diagnosis:'Verdacht auf lokale Perikoronitis Zahn 48',patientReply:['Seit etwa drei Tagen ist es hinten rechts unangenehm.','Beim Kauen wird es schlimmer, der Schmerz hält eine Weile an.','Nachts stört es, aber ich kann schlafen.','Ich habe bisher kein Fieber, keine Schluckstörung und keine Schwellung bemerkt.','Ja, bitte schauen Sie nach.','Brauche ich jetzt ein Antibiotikum?','Ich möchte wissen, ob der Weisheitszahn herausmuss.'],vocab:[['die Perikoronitis','inflamed operculum'],['der Weisheitszahn','third molar'],['die Mundöffnung','mouth opening'],['die Extraktion','extraction'],['die Schwellung','swelling'],['der Hebel','elevator']],keywords:['48','Perikoronitis','Schwellung','Weisheits'],prepType:'SURGERY',qp:'Wann wird aus einer lokalen Perikoronitis ein dringlicher Infektionsfall?'},
 {id:'perio',num:'46',name:'Herr Tobias Richter',age:51,title:'Parodontalbefund am Zahn 46',subtitle:'Periodontology · instrument selection',complaint:'„Mein Zahnfleisch blutet oft beim Putzen und rechts unten fühlt sich ein Zahn manchmal locker an.“',history:'Wiederkehrendes Zahnfleischbluten, unregelmäßige Prophylaxe; Rauchstatus und Diabetesanamnese gezielt erfragen. Keine gesicherte parodontale Diagnose vor vollständigem Status.',exam:'Am Zahn 46 Blutung bei Sondierung, erhöhte Sondierungstiefe möglich. Vollständiger parodontaler Status, Lockerung, Furkation, Plaque- und Knochenbefund erforderlich.',risk:'Verdacht auf parodontale Erkrankung; Stadium und Grad erst nach vollständiger Diagnostik bestimmen.',planA:'Systematische parodontale Therapie nach Diagnostik einschließlich Aufklärung, Mundhygieneinstruktion, supra-/subgingivaler Instrumentierung nach Indikation und Reevaluation.',planB:'Bei unzureichendem Ansprechen stufengerechte Weiterbehandlung, ggf. chirurgische Maßnahmen; Prognose und Risikofaktoren beachten.',diagnosis:'Verdacht auf Parodontitis',patientReply:['Das Zahnfleisch blutet schon seit Monaten beim Putzen.','Beim Kauen habe ich selten Beschwerden.','Manchmal fühlt es sich lockerer an, besonders morgens.','Ich rauche ungefähr zehn Zigaretten am Tag; Diabetes wurde noch nicht untersucht.','Ja, eine Zahnfleischmessung ist in Ordnung.','Können meine Zähne durch Parodontitis ausfallen?','Ich würde gern wissen, was ich selbst verbessern kann.'],vocab:[['die Parodontitis','periodontitis'],['die Sondierungstiefe','probing depth'],['das Furkationsgebiet','furcation'],['die Kürette','curette'],['die Blutung auf Sondieren','bleeding on probing'],['die Reevaluation','reassessment']],keywords:['46','Zahnfleisch','Sondierung','Parodont'],prepType:'PERIO',qp:'Welche klinischen Befunde braucht man für eine moderne Parodontitisdiagnose?'}

];
