class PrepCanvas{
 constructor(canvas,onChange){this.strokeCount=0;this.pathLengthPx=0;this.canvas=canvas;this.ctx=canvas.getContext('2d');this.onChange=onChange;this.removed=new Set();this.overcut=0;this.active=false;this.last=null;this.caseId='molar';canvas.addEventListener('pointerdown',e=>{this.strokeCount++;this.active=true;this.last=null;canvas.setPointerCapture(e.pointerId);this.stroke(e)});canvas.addEventListener('pointermove',e=>{if(this.active)this.stroke(e)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>{this.active=false;this.last=null});this.draw()}
 setCase(id){this.caseId=id;this.reset()}
 reset(){this.removed.clear();this.overcut=0;this.strokeCount=0;this.pathLengthPx=0;this.last=null;this.draw();this.onChange?.()}
 coords(e){const r=this.canvas.getBoundingClientRect();return [(e.clientX-r.left)*700/r.width,(e.clientY-r.top)*410/r.height]}
 target(x,y){let cx=350,cy=202,rx=79,ry=45;if(this.caseId==='endo'){cx=352;cy=210;rx=57;ry=54}if(this.caseId==='anterior'){cx=347;cy=214;rx=97;ry=29}if(this.caseId==='crown'){return this.tooth(x,y)&&((x-350)/125)**2+((y-214)/82)**2>1}return ((x-cx)/rx)**2+((y-cy)/ry)**2<=1}
 tooth(x,y){return ((x-350)/174)**2+((y-214)/127)**2<=1}
 stroke(e){const end=this.coords(e),start=this.last||end;const segment=Math.hypot(start[0]-end[0],start[1]-end[1]);this.pathLengthPx+=segment;const n=Math.max(1,Math.ceil(segment/7));for(let i=0;i<=n;i++){const x=start[0]+(end[0]-start[0])*i/n,y=start[1]+(end[1]-start[1])*i/n;for(let a=-9;a<=9;a+=6)for(let b=-9;b<=9;b+=6){const xx=x+a,yy=y+b,key=`${Math.round(xx/9)},${Math.round(yy/9)}`;if(!this.tooth(xx,yy)||this.removed.has(key))continue;this.removed.add(key);if(!this.target(xx,yy))this.overcut++;}}this.last=end;this.draw();this.onChange?.()}
 coverage(){let total=0,done=0;for(let x=150;x<=550;x+=9)for(let y=80;y<=350;y+=9){if(!this.target(x,y))continue;total++;const ix=Math.round(x/9),iy=Math.round(y/9);let found=false;for(let dx=-1;dx<=1&&!found;dx++)for(let dy=-1;dy<=1;dy++)if(this.removed.has(`${ix+dx},${iy+dy}`)){found=true;break}if(found)done++}return Math.round(100*done/Math.max(total,1))}
 measures(){
  const target=new Set();const cutInside=new Set();const cutOff=new Set();
  for(let x=150;x<=550;x+=9)for(let y=80;y<=350;y+=9){if(this.target(x,y))target.add(`${Math.round(x/9)},${Math.round(y/9)}`)}
  for(const key of this.removed){const [xi,yi]=key.split(',').map(Number),x=xi*9,y=yi*9;if(!this.tooth(x,y))continue;(this.target(x,y)?cutInside:cutOff).add(key)}
  const intersections=[...cutInside].filter(x=>target.has(x)).length;
  const coveragePct=Math.round(100*intersections/Math.max(1,target.size));
  const precisionPct=Math.round(100*intersections/Math.max(1,cutInside.size+cutOff.size));
  const offTargetPct=Math.round(100*cutOff.size/Math.max(1,cutInside.size+cutOff.size));
  return {coveragePct,precisionPct,offTargetPct,overcutCells:cutOff.size,removedCells:cutInside.size+cutOff.size,targetCells:target.size,strokeCount:this.strokeCount,pathLengthPx:Math.round(this.pathLengthPx)};
 }
 acceptable(){const m=this.measures();return m.coveragePct>=70&&m.offTargetPct<=18}

 draw(){const g=this.ctx,c=this.canvas;g.clearRect(0,0,700,410);const grad=g.createLinearGradient(0,30,700,360);grad.addColorStop(0,'#14344b');grad.addColorStop(1,'#0a2330');g.fillStyle=grad;g.fillRect(0,0,700,410);g.strokeStyle='#335569';g.lineWidth=1;for(let x=50;x<700;x+=50){g.beginPath();g.moveTo(x,0);g.lineTo(x,410);g.stroke()}for(let y=50;y<410;y+=50){g.beginPath();g.moveTo(0,y);g.lineTo(700,y);g.stroke()}
 g.save();g.translate(350,214);g.scale(1.04,.99);g.beginPath();g.moveTo(-170,-37);g.bezierCurveTo(-177,-106,-115,-130,-45,-120);g.bezierCurveTo(-15,-136,19,-132,48,-120);g.bezierCurveTo(137,-135,179,-92,176,-25);g.bezierCurveTo(178,22,149,104,90,124);g.bezierCurveTo(50,134,26,121,2,118);g.bezierCurveTo(-38,129,-78,139,-122,115);g.bezierCurveTo(-166,84,-182,14,-170,-37);g.closePath();const enamel=g.createLinearGradient(-100,-130,120,128);enamel.addColorStop(0,'#f8efdc');enamel.addColorStop(.55,'#e6d5b5');enamel.addColorStop(1,'#c9b695');g.fillStyle=enamel;g.fill();g.lineWidth=9;g.strokeStyle='#f8f5eb';g.stroke();g.restore();
 g.strokeStyle='#947f66';g.lineWidth=3;g.beginPath();g.moveTo(241,206);g.quadraticCurveTo(310,170,348,213);g.quadraticCurveTo(386,170,460,208);g.moveTo(350,130);g.quadraticCurveTo(331,174,349,219);g.quadraticCurveTo(374,265,353,301);g.stroke();
 const t=this.caseId==='endo'?{rx:57,ry:54,cy:210}:this.caseId==='anterior'?{rx:97,ry:29,cy:214}:this.caseId==='crown'?{rx:164,ry:118,cy:214}:{rx:79,ry:45,cy:202};g.beginPath();g.ellipse(350,t.cy,t.rx,t.ry,0,0,Math.PI*2);g.fillStyle='#a85b44a8';g.fill();if(this.caseId==='crown'){g.beginPath();g.ellipse(350,214,125,82,0,0,Math.PI*2);g.fillStyle='#e7d6b9';g.fill()}g.strokeStyle='#eabf82';g.setLineDash([6,5]);g.lineWidth=2;g.stroke();g.setLineDash([]);
 for(const p of this.removed){const [i,j]=p.split(',').map(Number),x=i*9,y=j*9;g.beginPath();g.arc(x,y,8.5,0,Math.PI*2);g.fillStyle=this.target(x,y)?'#5b625b':'#944c54';g.fill()}
 g.fillStyle='#e1f4ed';g.font='700 12px system-ui';g.fillText('OCCLUSAL · SIMULATED TOOTH',24,29);g.font='11px system-ui';g.fillStyle='#9db9c4';g.fillText('Shaded area = practice target',24,50);g.strokeStyle='#91e2cc';g.lineWidth=2;g.strokeRect(10,10,680,390);
 }
}
class KlinikApp {
 constructor(){this.actionTrace=[];this.caseIndex=0;this.stationIndex=4;this.expert=true;this.revealed=false;this.freeResponse='';this.step=0;this.done=false;this.revealed=false;this.freeResponse='';this.response='';this.feedbackText='';this.feedbackType='';this.selectedTooth='';this.selectedTool='';this.viewMode='3d';this.local=this.load();this.letterDraft={};this.planDraft={};this.procedure=new PrepCanvas($('drill'),()=>this.updatePrep());this.procedure.setCase(this.caseData.id);try{this.scene=new DentalScene($('scene'),key=>this.onScenePick(key));this.scene.focusTeeth()}catch(e){try{this.scene=new DentalSceneFallback($('scene'),key=>this.onScenePick(key));this.scene.focusTeeth();$('scene-label').textContent='Interactive 3D dental model';document.querySelector('[data-view="3d"]').textContent='3D anatomy';$('stage-hint').textContent='3D desktop mode · Drag orbit · Wheel zoom · Select teeth · VR requires WebGL';$('vr').disabled=true;$('vr').title='Immersive VR requires a WebGL-capable headset';}catch(error){this.scene=null;$('stage-hint').textContent='3D unavailable: '+error.message}}this.scene?.setCaseTooth?.(this.caseData.num);this.bind();this.renderNav();this.renderChart();this.renderTray();this.render();this.checkXR()}
 get caseData(){return CASES[this.caseIndex]}get station(){return STATIONS[this.stationIndex]}
 recordAction(action,detail,correct=null){this.actionTrace.push({action,step:this.station.id+' / '+(this.step+1),detail:String(detail||'').slice(0,230),correct});if(this.actionTrace.length>80)this.actionTrace.shift()}
 load(){try{const s=JSON.parse(localStorage.getItem('KlinikLab_v3')||'{}');return {complete:Array.isArray(s.complete)?s.complete:[],correct:Math.max(0,s.correct||0)}}catch{return {complete:[],correct:0}}}
 save(){try{localStorage.setItem('KlinikLab_v3',JSON.stringify(this.local))}catch{}}
 bind(){
  const closeNav=()=>{$('training-nav').classList.remove('open');$('mobile-scrim').classList.remove('open');$('open-nav').setAttribute('aria-expanded','false')};
  const openNav=()=>{$('training-nav').classList.add('open');$('mobile-scrim').classList.add('open');$('open-nav').setAttribute('aria-expanded','true');$('close-nav').focus()};
  $('training-nav').addEventListener('click',ev=>{if(ev.target.closest('.case,.station'))closeNav()});$('open-nav').onclick=openNav;$('case-quick').onclick=openNav;$('close-nav').onclick=()=>{closeNav();$('open-nav').focus()};$('mobile-scrim').onclick=closeNav;
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeNav()});
  $('jump-exercise').onclick=()=>document.querySelector('.right').scrollIntoView({behavior:'smooth',block:'start'});
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>this.setView(b.dataset.view));$('focus').onclick=()=>{this.setView('3d');this.scene?.focusTeeth();$('scene-label').textContent='3D dental anatomy · interactive'};$('room').onclick=()=>{this.setView('3d');this.scene?.focusRoom();$('scene-label').textContent='Clinic orientation · schematic'};$('arches').onclick=()=>{if(!this.scene)return;const mode=this.scene.cycleArches();$('arches').textContent={both:'Both arches',upper:'Upper only',lower:'Lower only'}[mode]};$('occlusal').onclick=()=>{this.setView('3d');this.scene?.occlusalView();$('arches').textContent={both:'Both arches',upper:'Upper only',lower:'Lower only'}[this.scene.archMode]};$('next').onclick=()=>this.next();$('restart').onclick=()=>this.selectStation(this.stationIndex);$('expert').onclick=()=>{this.expert=!this.expert;this.revealed=false;$('expert').textContent='Expert: '+(this.expert?'ON':'OFF');this.render()};$('help').onclick=()=>{if(!window.KlinikTutorial?.open?.())this.toast('Guided tour unavailable. Please reload KlinikLab.')};$('reset').onclick=()=>{if(confirm('Reset locally stored session progress?')){this.local={complete:[],correct:0};this.save();this.renderNav()}};$('vr').onclick=()=>this.toggleVR()}
 async toggleVR(){
  if(this.vrBusy)return false;
  const scene=this.scene;
  if(!scene||(!scene.xrSession&&typeof scene.enterVR!=='function')){this.toast('Immersive VR requires the WebGL renderer and a compatible browser.');return false;}
  const btn=$('vr'),label=btn.textContent,disabled=btn.disabled,exiting=!!scene.xrSession;
  this.vrBusy=true;btn.disabled=true;btn.setAttribute('aria-busy','true');btn.textContent=exiting?'Leaving VR…':'Starting VR…';
  try{
   // Call directly from the click; do not await a capability probe first.
   if(exiting)await scene.xrSession.end();else await scene.enterVR();
   this.toast(exiting?'VR session ended':'VR session activated');return true;
  }catch(e){this.toast(e?.message||(exiting?'Could not leave VR. Try again.':'Could not open VR. Try again.'));return false;}
  finally{this.vrBusy=false;btn.disabled=disabled;btn.textContent=label;btn.removeAttribute('aria-busy');}
 }
 async checkXR(){const btn=$('vr');if(!navigator.xr||!window.isSecureContext){btn.title='Quest VR requires HTTPS and a compatible headset';return}try{const ok=await navigator.xr.isSessionSupported('immersive-vr');btn.disabled=!ok;btn.title=ok?'Enter immersive Quest VR':'VR unavailable in this browser'}catch{btn.disabled=true}}
 toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>t.classList.remove('show'),2000)}
 renderNav(){for(const [track,container] of [['fsp','fsp-stations'],['kp','kp-stations'],['clinic','clinic-stations']])$(container).innerHTML=STATIONS.map((s,i)=>({s,i})).filter(x=>x.s.track===track).map(({s,i})=>`<button class="station ${i===this.stationIndex?'active':''}" data-station="${i}"><span class="num">${s.icon}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.short)}</small></span><span class="check">${this.local.complete.includes(s.id+'_'+this.caseData.id)?'✓':''}</span></button>`).join('');$('cases').innerHTML=CASES.map((c,i)=>`<button class="case ${i===this.caseIndex?'active':''}" data-case="${i}"><span class="tooth-num">${c.num}</span><span><strong>${esc(c.title)}</strong><small>${esc(c.subtitle)}</small></span></button>`).join('');document.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>this.selectStation(+b.dataset.station));document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>this.selectCase(+b.dataset.case));$('progress-label').textContent=`${this.local.complete.filter(s=>s.endsWith('_'+this.caseData.id)).length} / 7`;$('progress-fill').style.width=`${100*this.local.complete.filter(s=>s.endsWith('_'+this.caseData.id)).length/7}%`;$('correct-label').textContent=this.local.correct}
 selectCase(index){if(!CASES[index])return;this.caseIndex=index;this.procedure.setCase(this.caseData.archetype||this.caseData.id);this.volLab?.setCase(this.caseData.archetype||this.caseData.id);this.resetStation();this.scene?.select('');this.scene?.setArchMode('both');$('arches').textContent='Both arches';this.scene?.focusTeeth();this.scene?.setCaseTooth?.(this.caseData.num);this.renderNav();this.renderChart();this.render();}
 selectStation(index){if(!STATIONS[index])return;this.stationIndex=index;this.resetStation();this.renderNav();this.render();}
 resetStation(){this.step=0;this.done=false;this.revealed=false;this.freeResponse='';this.response='';this.feedbackText='';this.feedbackType='';this.letterDraft={};this.planDraft={};this.procedure.reset();this.actionTrace=[];this.setView('3d');}
 setView(mode){this.viewMode=mode;$('procedure').classList.toggle('active',mode==='operative');$('volume-root')?.classList.toggle('active',mode==='volume');$('xray').classList.toggle('active',mode==='xray');$('scene').classList.toggle('hidden',mode!=='3d');$('stage-hint').classList.toggle('hidden',mode!=='3d');$('selected-label').classList.toggle('hidden',mode!=='3d');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));this.scene?.resize();if(mode==='operative')this.procedure.draw();if(mode==='volume')this.volLab?.activate()}
 renderChart(){const groups=[[18,17,16,15,14,13,12,11],[21,22,23,24,25,26,27,28],[48,47,46,45,44,43,42,41],[31,32,33,34,35,36,37,38]];let html='';groups.forEach((g,i)=>{html+=`<div class="chartlabel"><span>${i<2?'MAXILLA':'MANDIBLE'} · ${i%2===0?'right':'left'}</span><span>FDI</span></div><div class="chart">${g.map(n=>`<button class="tooth ${this.selectedTooth===String(n)?'selected':''} ${String(n)===this.caseData.num?'case-tooth':''}" data-tooth="${n}" aria-label="Tooth ${n}">${n}</button>`).join('')}</div>`});$('chart').innerHTML=html;document.querySelectorAll('[data-tooth]').forEach(b=>b.onclick=()=>this.selectTooth(b.dataset.tooth))}
 renderTray(){$('tray').innerHTML=Object.entries(TOOLS).map(([key,v])=>`<button class="tool ${this.selectedTool===key?'selected':''}" data-tool="${key}" title="${esc(v[1])}">${esc(v[0])}</button>`).join('');document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>this.selectTool(b.dataset.tool))}
 onScenePick(key){if(key.startsWith('tooth:'))this.selectTooth(key.slice(6));else if(key.startsWith('tool:'))this.selectTool(key.slice(5));else if(key.startsWith('module:'))this.selectStation(+key.slice(7));else if(key.startsWith('answer:'))this.choose(+key.slice(7))}
 selectTooth(id){this.recordAction('tooth_selection','FDI '+id,id===this.caseData.num);this.selectedTooth=id;this.selectedTool='';this.scene?.select('tooth:'+id);$('selected-label').textContent='Selected tooth: '+id;this.renderChart();this.renderTray();if(this.station.id==='practical'&&!this.done){const s=this.practicalStep();if(s?.type==='tooth')this.processTarget(s,id,'tooth')}else this.report(`Tooth ${id} selected. Current training tooth: ${this.caseData.num}.`,'')}
 selectTool(id){this.recordAction('instrument_selection',TOOLS[id]?.[0]||id,(this.station.id==='practical'&&this.practicalStep()?.type==='tool')?this.practicalStep().target===id:null);this.selectedTool=id;this.selectedTooth='';this.scene?.select('tool:'+id);$('selected-label').textContent='Selected: '+TOOLS[id]?.[0];this.renderChart();this.renderTray();if(this.station.id==='practical'&&!this.done){const s=this.practicalStep();if(s?.type==='tool')this.processTarget(s,id,'tool')}else this.report(`${TOOLS[id]?.[0]} selected. ${TOOLS[id]?.[1]}.`,'')}
 processTarget(s,value,type){if(s.target===value){this.local.correct++;this.save();this.markStepDone(s.success||'Correct action.');this.toast('✓ Correct');}else this.report(`Incorrect ${type==='tooth'?'tooth':'instrument'}. Recheck the case and try again.`,'bad')}
 report(s,type=''){this.feedbackText=s;this.feedbackType=type;const e=$('feedback');e.className='feedback'+(type?' '+type:'');e.textContent=s}
 markStepDone(s){this.done=true;this.report(s,'ok');this.syncButton();this.syncXR()}
 practicalStep(){return getPractical(this.caseData)[this.step]}
 choose(i){const s=this.getCurrentChoice();if(!s||this.done)return;if(i<0||i>=s.options.length)return;const ok=i===s.correct;this.recordAction('clinical_decision',s.title+' / '+(s.options[i]||''),ok);document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=ok;if(+b.dataset.answer===i)b.classList.add(ok?'good':'bad')});if(ok){$('choice-options')?.classList.remove('hidden');this.local.correct++;this.save();const reply=this.station.id==='interview'?this.caseData.patientReply[Math.min(this.step,this.caseData.patientReply.length-1)]:null;this.response=reply||'';this.markStepDone(s.why||s.explain||'Correct.');this.toast('✓ Correct');if(reply)this.renderResponse()}else this.report(s.why||s.explain||'Consider the options and try again.','bad')}
 getCurrentChoice(){const id=this.station.id;if(id==='interview')return FSP_DIALOGUE[this.step];if(id==='handover')return HANDOVER[this.step];if(id==='viva')return VIVA[this.step];if(id==='clinic')return CLINIC[this.step];if(id==='practical'){const step=this.practicalStep();return step?.type==='choice'?step:null}return null}
 next(){if(!this.done){if(this.station.id==='letter')this.evaluateLetter();else if(this.station.id==='written')this.evaluatePlan();else if(this.station.id==='practical'&&this.practicalStep()?.type==='drill')this.evaluatePrep();else this.report('Complete the current task, then continue.','bad');return}let n=this.totalSteps();if(this.step<n-1){this.step++;this.done=false;this.revealed=false;this.freeResponse='';this.response='';this.report('Ready for the next decision.');this.render();return}const key=this.station.id+'_'+this.caseData.id;if(!this.local.complete.includes(key))this.local.complete.push(key);this.save();this.toast('★ Station completed');this.renderNav();this.render();}
 totalSteps(){const id=this.station.id;return id==='interview'?FSP_DIALOGUE.length:id==='handover'?HANDOVER.length:id==='viva'?VIVA.length:id==='clinic'?CLINIC.length:id==='practical'?getPractical(this.caseData).length:1}
 isComplete(){return this.done&&this.step===this.totalSteps()-1}
 syncButton(){const btn=$('next');if(this.isComplete()){btn.textContent='Finish station ✓';btn.disabled=false}else if(this.done){btn.textContent='Next step →';btn.disabled=false}else{btn.textContent=this.station.id==='letter'?'Review Arztbrief':this.station.id==='written'?'Review treatment plans':this.station.id==='practical'&&this.practicalStep()?.type==='drill'?'Evaluate outline':'Continue →';btn.disabled=false}}
 renderResponse(){const r=$('patient-response');if(r)r.innerHTML=`<b>Patientin / Patient:</b> „${esc(this.response)}“ <button class="btn tiny" id="speak-reply" style="float:right">▶ hören</button>`;const b=$('speak-reply');if(b)b.onclick=()=>this.speak(this.response)}
 speak(text){if(!('speechSynthesis'in window)){this.toast('Speech synthesis not supported');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.88;speechSynthesis.speak(u)}
 render(){const c=this.caseData,s=this.station;$('station-label').textContent=`${s.track==='fsp'?'FSP':s.track==='kp'?'KP':'PRAXIS'} · ${s.icon} / 07`;$('station-title').textContent=s.name;$('station-desc').textContent=s.desc;$('patient-name').textContent=`${c.name} · ${c.age} Jahre`;$('patient-note').textContent=c.complaint;$('case-strip-title').textContent=`Fall ${String(this.caseIndex+1).padStart(2,'0')} · ${c.title}`;$('case-strip-meta').textContent=`${c.subtitle} · Zahn ${c.num} · fictional case`;$('vocab').innerHTML=c.vocab.map(([a,b])=>`<div><b>${esc(a)}</b><span>${esc(b)}</span></div>`).join('');$('film-marker').setAttribute('cx',c.id==='anterior'?'126':c.id==='endo'?'367':'372');let html='';if(s.id==='letter')html=this.letterView();else if(s.id==='written')html=this.writtenView();else if(s.id==='practical')html=this.practicalView();else {let q=this.getCurrentChoice();html=this.choiceView(q)}$('workspace').innerHTML=html;this.bindWorkspace();this.renderResponse();this.syncButton();this.syncXR();if(!this.feedbackText)this.report(s.id==='letter'?'Write a professional German report. The real FSP requires handwritten writing.':s.id==='written'?'Formulate your own two justified plans; compare indications, risks and alternatives.':s.id==='practical'?'Carry out the training sequence in the interactive model and operative workspace.':'Choose the clinically appropriate response and explain it aloud in German.');else this.report(this.feedbackText,this.feedbackType)}
 choiceView(q){if(!q)return '';const current=this.step+1,total=this.totalSteps();return `<div class="task"><span class="counter">TASK ${current} / ${total} · ${this.station.id==='interview'?'PATIENTENSPRACHE':'KLINISCHE ENTSCHEIDUNG'}</span><h2>${esc(q.title||q.topic||'Prüfungsfrage')}</h2><p>${esc(q.prompt||q.detail||q.question||q.q)}</p></div>${this.expert?`<div class="active-recall"><strong>Freie Antwort · zuerst selbst formulieren</strong><p>Answer aloud in German and write a short reasoning note before revealing the suggested responses.</p><textarea class="draft" id="free-response" placeholder="Meine Antwort auf Deutsch …">${esc(this.freeResponse||'')}</textarea><button class="btn tiny" id="reveal-answers">${this.revealed?'Answer options visible':'Reveal response choices'}</button></div>`:''}<div class="options ${this.expert&&!this.revealed&&!this.done?'hidden':''}" id="choice-options">${q.options.map((o,i)=>`<button class="option ${this.done&&i===q.correct?'good':''}" data-answer="${i}" ${this.done?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div>${this.station.id==='interview'?`<div class="response" id="patient-response"><b>Patientenreaktion</b><i>Select a professional question to hear the response.</i></div><div class="rubric"><h3>Speaking rehearsal · C1 Fachsprache</h3><p>Read your selected phrase aloud first, then choose it. Listen to the patient's answer and repeat the exchange naturally.</p><button class="btn tiny" id="speak-question">▶ Model phrase</button> <button class="btn tiny" id="mic">🎙 Speak (beta)</button><div id="transcript" style="margin-top:7px;color:#526f73;font-size:11px"></div></div>`:this.station.id==='handover'?`<div class="rubric"><h3>Colleague discussion</h3><p>Explain why the answer is clinically and linguistically preferable using precise German dental terminology.</p></div>`:''}`}
 letterView(){const c=this.caseData;return `<div class="task"><span class="counter">FSP · SCHRIFTLICHER TEIL</span><h2>Arztbrief: ${esc(c.name)}</h2><p>Use the clinical information after the simulated anamnesis. Reproduce the structure by hand separately for realistic exam training; this text editor is for drafting and feedback.</p></div><div class="inline-note"><b>Case file:</b> ${esc(c.history)} ${esc(c.exam)}</div><div class="brief-grid"><div><label class="fieldlabel" for="d-anamnese">Anamnese und Leitsymptom</label><textarea class="draft" id="d-anamnese" placeholder="Die Patientin stellte sich aufgrund von ... vor.">${esc(this.letterDraft.anamnese||'')}</textarea></div><div><label class="fieldlabel" for="d-befund">Untersuchungsbefund</label><textarea class="draft" id="d-befund" placeholder="Klinisch zeigte sich am Zahn ...">${esc(this.letterDraft.befund||'')}</textarea></div><div><label class="fieldlabel" for="d-diagnose">Verdachts-/Differenzialdiagnose</label><textarea class="draft" id="d-diagnose" placeholder="Es besteht der Verdacht auf ...">${esc(this.letterDraft.diagnose||'')}</textarea></div><div><label class="fieldlabel" for="d-therapie">Therapie / weiteres Vorgehen</label><textarea class="draft" id="d-therapie" placeholder="Wir empfehlen nach Aufklärung ...">${esc(this.letterDraft.therapie||'')}</textarea></div></div><div class="rubric"><h3>Checklist for self-review</h3><p>Neutral language · clinically accurate findings · uncertainty stated · justified alternatives · explanation/consent recorded</p><p>This is keyword/structure feedback, not a handwriting assessment or language certification.</p></div>`}
 writtenView(){const c=this.caseData;return `<div class="task"><span class="counter">KP · SCHRIFTLICHE PLANUNG</span><h2>Zwei Therapiealternativen begründen</h2><p>Develop at least two proposals from symptoms, periodontal assessment, diagnostic tests, restorability and imaging where indicated.</p></div><div class="inline-note"><b>Clinical material:</b> ${esc(c.history)} ${esc(c.exam)}</div><label class="fieldlabel">Arbeitsdiagnose und erforderliche Zusatzbefunde</label><textarea class="draft" id="p-diagnosis" placeholder="Begründen Sie Ihre Arbeitsdiagnose; welche Tests sind noch erforderlich?">${esc(this.planDraft.diagnosis||'')}</textarea><label class="fieldlabel">Behandlungsplan A — Zahnerhalt / bevorzugte Option</label><textarea class="draft" id="p-planA" placeholder="Indikation, Vorgehen, Prognose, Nutzen, Risiken ...">${esc(this.planDraft.planA||'')}</textarea><label class="fieldlabel">Behandlungsplan B — Alternative</label><textarea class="draft" id="p-planB" placeholder="Alternative Therapie einschließlich Vor- und Nachteilen ...">${esc(this.planDraft.planB||'')}</textarea><label class="fieldlabel">Aufklärung, Einwilligung, Nachsorge</label><textarea class="draft" id="p-followup" placeholder="Patientenpräferenz, Einwilligung, Kontrollen ...">${esc(this.planDraft.followup||'')}</textarea><details class="rubric"><summary><b>Reveal sample reasoning after your own answer</b></summary><p>Option A: ${esc(c.planA)}</p><p>Option B: ${esc(c.planB)}</p><p>These are illustrative alternatives, not definitive plans for a real patient.</p></details>`}
 practicalView(){const q=this.practicalStep(),n=getPractical(this.caseData).length;if(!q)return '';const type=q.type;if(type==='choice')return this.choiceView(q);return `<div class="task"><span class="counter">KP PRAKTISCH · STEP ${this.step+1} / ${n}</span><h2>${esc(q.title)}</h2><p>${esc(q.detail)}</p></div>${type==='drill'?`<div class="rubric"><h3>Interactive preparation target</h3><p>Open <b>3D Präparation</b>, inspect the enamel, dentin and pulp layers in the cutaway view, then create a volumetric preparation. Compare the geometric metrics; this is not a clinical competency assessment.</p><button id="open-operative" class="btn primary">Open 3D procedure lab →</button> <button id="reset-prep" class="btn">Reset cut</button><p id="drill-readout">Coverage: ${this.procedure.coverage()}%. Overcut: ${this.procedure.overcut}.</p></div>`:`<div class="rubric"><h3>${type==='tooth'?'FDI accuracy':'Instrument selection'}</h3><p>Use the interactive 3D dental model or the odontogram/instrument tray below the 3D view.</p></div>`}`}
 bindWorkspace(){document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>this.choose(+b.dataset.answer));$('reveal-answers')?.addEventListener('click',()=>{this.revealed=true;$('choice-options')?.classList.remove('hidden');$('reveal-answers').textContent='Answer options visible'});$('free-response')?.addEventListener('input',e=>this.freeResponse=e.target.value);$('speak-question')?.addEventListener('click',()=>{const q=this.getCurrentChoice();this.speak(q.options[q.correct])});$('mic')?.addEventListener('click',()=>this.listen());$('open-operative')?.addEventListener('click',()=>this.setView('volume'));$('reset-prep')?.addEventListener('click',()=>{this.procedure.reset();this.volLab?.reset()});for(const type of ['anamnese','befund','diagnose','therapie']){const el=$('d-'+type);if(el)el.oninput=()=>{this.letterDraft[type]=el.value}}for(const type of ['diagnosis','planA','planB','followup']){const el=$('p-'+type);if(el)el.oninput=()=>{this.planDraft[type]=el.value}}}
 listen(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){this.report('Speech recognition is unavailable in this browser. Read the German sentences aloud or use the model audio.','');return}try{const r=new SpeechRecognition();r.lang='de-DE';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const result=e.results[0][0].transcript;$('transcript').textContent='You said: '+result+' · Review your phrasing; automated speech grading is not provided.'};r.onerror=e=>this.report('Microphone unavailable: '+e.error);r.start();this.toast('Listening in German…')}catch(e){this.report('Microphone could not start: '+e.message)}}
 evaluateLetter(){const keys=['anamnese','befund','diagnose','therapie'];const lens=keys.map(k=>(this.letterDraft[k]||'').trim().length);const good=lens.filter(n=>n>=35).length;const sample=`${this.letterDraft.anamnese||''} ${this.letterDraft.befund||''} ${this.letterDraft.diagnose||''} ${this.letterDraft.therapie||''}`.toLowerCase();const containsTooth=sample.includes(this.caseData.num);if(good<4){this.report(`Draft coverage ${good}/4 sections. Complete all four with meaningful clinical information before review.`,`bad`);return}this.markStepDone(`Structure check passed (4/4 sections). ${containsTooth?'FDI tooth reference present.':'Check that tooth '+this.caseData.num+' is specified accurately.'} Review grammatical accuracy, reported vs observed findings, clinical uncertainty, alternatives and consent yourself. This is not a formal FSP assessment.`)}
 evaluatePlan(){const keys=['diagnosis','planA','planB','followup'];const lengths=keys.map(k=>(this.planDraft[k]||'').trim().length);const good=lengths.filter(n=>n>=35).length;if(good<4){this.report(`Written plan draft ${good}/4 fields substantially completed. Document the working diagnosis, two distinct options, justification and follow-up.`,'bad');return}const a=this.planDraft.planA.toLowerCase(),b=this.planDraft.planB.toLowerCase();if(a===b){this.report('Plan A and Plan B must describe two different alternatives.','bad');return}this.markStepDone(`Your written submission includes a diagnosis, two distinct plans and follow-up. Self-check: does each option address indications, prognosis, risks, patient preference and potential costs? This is a structural check, not clinical grading.`)}
 evaluatePrep(){const v=this.volLab&&this.volLab.solid.bur.length?this.volLab.measures():null;if(v){this.recordAction('volumetric_3d_preparation',JSON.stringify(v),null);if(v.pulpExposure&&v.procedure!=='endo'){this.report('Simulierte Pulpaeröffnung. Prüfen Sie Indikation, Anatomie und konservatives Vorgehen; diese Modellwarnung ersetzt keine klinische Beurteilung.','bad');return}if(v.procedure==='endo'&&!v.pulpExposure){this.report('Endodontische Zugangskavität: Die modellierte Pulpakammer ist noch nicht erreicht. Überprüfen Sie die Zugangsachse und Tiefe im Schnittbild. Diese Geometrie ist nicht klinisch kalibriert.','bad');return}if(v.coveragePct<55){this.report(`3D Zielvolumen zu ${v.coveragePct}% bearbeitet. Erhöhen Sie die Zielabdeckung, ohne unnötig gesunde Zahnhartsubstanz zu entfernen. Kein offizieller KP-Grenzwert.`,'bad');return}if(v.offTargetPct>28){this.report(`3D Überpräparation: ${v.offTargetPct}% des abgetragenen Modellvolumens lag außerhalb des Übungsziels. Prüfen Sie Ihr Vorgehen. Kein offizieller KP-Grenzwert.`,'bad');return}this.markStepDone(`3D-Übung ausgewertet: ${v.coveragePct}% simulierte Zielabdeckung, ${v.precisionPct}% Präzision, ${v.pulpExposure?(v.procedure==='endo'?'simulierter Zugang zur Pulpakammer':'Pulpa im Modell eröffnet'):'keine simulierte Pulpakammereröffnung'}. Nur modellinterne Lernkennzahlen, keine klinische Qualitätszertifizierung.`);return}const pct=this.procedure.coverage(),oc=this.procedure.overcut;this.recordAction('schematic_outline',JSON.stringify(this.procedure.measures()),this.procedure.acceptable());if(pct<70){this.report(`2D target coverage ${pct}%. No 3D technique was measured.`,'bad');return}if(oc>35){this.report(`2D overcut ${oc} samples.`,'bad');return}this.markStepDone(`2D outline coverage ${pct}% with ${oc} overcut samples; no depth, tactile force or clinical skill was assessed.`)}
 updatePrep(){$('proc-metrics').textContent=`Target ${this.procedure.coverage()}% · Overcut ${this.procedure.overcut}`;const r=$('drill-readout');if(r)r.textContent=`Coverage: ${this.procedure.coverage()}%. Overcut: ${this.procedure.overcut}.`}
 syncXR(){if(!this.scene)return;const q=this.getCurrentChoice();const ans=q&&!this.done?q.options.map(x=>x.slice(0,42)):[];this.scene.setVRState({title:this.station.name.toUpperCase(),step:(this.station.id==='practical'?this.practicalStep()?.title:q?.title||'Complete on desktop').slice(0,43),module:this.stationIndex,answers:ans});}
}
window.addEventListener('DOMContentLoaded',()=>{window.kliniklab=new KlinikApp()});
